// Verificacion de la firma de Stripe.
//
// POR QUE ESTO NO ES OPCIONAL
// ---------------------------
// Un webhook es una URL publica que acepta POST. Sin verificar la firma,
// cualquiera que la descubra puede mandar un `checkout.session.completed`
// inventado y marcar leads como pagados: contabilidad falseada, secuencias
// detenidas para gente que no ha pagado, y metricas de embudo inservibles.
//
// Se verifica segun el esquema de Stripe: HMAC-SHA256 de "<t>.<cuerpo crudo>"
// con el signing secret, comparado en tiempo constante, mas una tolerancia de
// tiempo que impide reutilizar una peticion legitima capturada (replay).

const crypto = require('crypto');

const secreto = $env.STRIPE_WEBHOOK_SECRET;
if (!secreto) {
  // Fallar aqui y no dejar pasar: sin secreto no hay verificacion posible, y
  // un webhook sin verificar es peor que un webhook caido.
  throw new Error(
    'Falta STRIPE_WEBHOOK_SECRET en el entorno de n8n. Sin el no se puede ' +
    'verificar la firma, y se aceptarian pagos inventados.'
  );
}

const entrada = $input.first();

// EL CUERPO TIENE QUE SER EL CRUDO, byte a byte.
// Si se usa el JSON ya parseado y se vuelve a serializar, el orden de las
// claves y los espacios cambian, el HMAC no coincide y TODO pago legitimo se
// rechaza. Por eso el nodo Webhook lleva `rawBody: true`.
const bin = entrada.binary && entrada.binary.data;
if (!bin) {
  throw new Error(
    'No hay cuerpo crudo. El nodo Webhook necesita la opcion "Raw Body" ' +
    'activada; sin ella la firma nunca va a validar.'
  );
}
const cuerpoCrudo = Buffer.from(bin.data, 'base64').toString('utf8');

const cabecera = entrada.json.headers['stripe-signature'] || '';
const partes = Object.fromEntries(
  cabecera.split(',').map((p) => p.split('=', 2)).filter((p) => p.length === 2)
);
const marca = partes.t;
if (!marca) throw new Error('Cabecera Stripe-Signature sin marca de tiempo.');

// Tolerancia de 5 minutos, la que recomienda Stripe. Sin esto, una peticion
// legitima capturada se puede reenviar indefinidamente.
const edad = Math.abs(Math.floor(Date.now() / 1000) - parseInt(marca, 10));
if (edad > 300) {
  throw new Error(`Peticion demasiado antigua (${edad} s). Posible replay.`);
}

const esperado = crypto
  .createHmac('sha256', secreto)
  .update(`${marca}.${cuerpoCrudo}`, 'utf8')
  .digest('hex');

// Puede venir mas de una v1 durante una rotacion de secreto: vale con que una
// case. La comparacion es en tiempo constante; una comparacion normal filtra
// la firma byte a byte por el tiempo de respuesta.
const firmas = cabecera
  .split(',')
  .map((p) => p.split('=', 2))
  .filter((p) => p[0] === 'v1')
  .map((p) => p[1]);

const bufEsperado = Buffer.from(esperado, 'hex');
const valida = firmas.some((f) => {
  const b = Buffer.from(f, 'hex');
  return b.length === bufEsperado.length && crypto.timingSafeEqual(b, bufEsperado);
});

if (!valida) throw new Error('Firma de Stripe invalida. Peticion descartada.');

const evento = JSON.parse(cuerpoCrudo);
const sesion = evento.data && evento.data.object ? evento.data.object : {};

return [{
  json: {
    event_id:     evento.id,
    tipo:         evento.type,
    lead_id:      sesion.client_reference_id || null,
    importe_cent: sesion.amount_total != null ? sesion.amount_total : null,
    moneda:       sesion.currency || null,
    email_pago:   (sesion.customer_details && sesion.customer_details.email) || null,
    payload:      JSON.stringify(evento),
  },
}];
